// ── Failure messages (scripts/core/friendlyError.js) ─────────────────────────
// Kept in its own block because these are the only strings in this file that
// are NOT translated by walking the DOM. friendlyText() glues message + hint
// into a single node, and that concatenation is not a key — so friendlyError.js
// calls window.PFX_t on the parts itself and these entries are what it finds.
//
// Two deliberate non-translations:
//   · "Resolve Engine", "Simple Mode", "IMF Validation" are absent from every
//     other dict, i.e. the UI shows them in English. An error that renamed them
//     would send the user hunting for a menu that does not exist.
//   · macOS ships no Indonesian or Filipino localisation, so those two keep
//     "System Settings › Privacy & Security" verbatim — it is what is actually
//     on screen for them. ko/ja/zh-TW/th use the localised pane names.
//
// tests-js/errorI18n.test.mjs fails if a friendlyError string is added without
// a translation here, so this cannot silently drift.
