    "Add Marker": "เพิ่มมาร์กเกอร์",
    "Edit Marker Metadata": "แก้ไขข้อมูลมาร์กเกอร์",
    "Delete Marker": "ลบมาร์กเกอร์",
    "Open Annotation": "เปิดคำอธิบายภาพ",
    "Edit Annotation": "แก้ไขคำอธิบายภาพ",
