// ── Locale parity backfill ────────────────────────────────────────────────
// Every entry below is a string that some locale rendered in its own language
// and at least one other locale had NO entry for at all — so t() fell through
// and returned the English key. Measured against the merged DICT above:
//
//   ko 128 · ja 129 · fil 47 · id 34 · th 21 · zh-TW 7   = 366 missing pairs
//
// The bulk of it is structural rather than random. The LOCALE_FULL_DICT block
// was authored for zh-TW/th/id/fil; ko and ja only ever received part of it,
// so Japanese and Korean users saw English for roughly a fifth of the UI —
// including Export, Duration, Status, Reset and the whole camera-profile
// panel.
//
// WHY THIS IS SMALLER THAN 366
// A dictionary entry whose value equals its key is not automatically a defect.
// Filipino post-production says "Lens Flare" and "Cut Diff"; Indonesian says
// "VFX Marker". Those locales prove it in their own existing entries — fil maps
// "PULL PREP" to "Pull Prep" deliberately. Adding key→key pairs for terms a
// locale keeps in English would satisfy a presence check while changing nothing
// a user sees, which is the same silent no-op this repo keeps finding in other
// forms. So the rule here is: an entry exists only where the value differs from
// the key. Where a locale genuinely keeps the English term, there is no entry,
// and i18nParity.test.mjs records that in its own separate baseline instead of
// pretending it is fixed.
//
// Merged with a gap-fill, NOT Object.assign. The three merges above intend to
// override; this one must never silently replace a string somebody authored.
